  else if (program === 'powershell' || program === 'pwsh') inner = args.findIndex(arg => /^-(c|command|commandwithargs)$/i.test(arg));
  else if (['bash', 'sh', 'zsh', 'dash'].includes(program)) inner = args.findIndex(arg => /^-[a-z]*c$/.test(arg));
